    cls=set\(\)
    for m in re.findall\(r'class="\([^"]*\)"',t\)+re.findall\(r"class='\([^']*\)'",t\):
        cls|=set\(m.split\(\)\)
    for m in re.findall\(r"'\([A-Za-z0-9_ -]+\)'",t\):  # ngClass strings
        cls|=set\(m.split\(\)\)
    for m in re.findall\(r"\\[class\\.\([A-Za-z0-9_-]+\)\\]",t\):
        cls.add\(m\)
